pub fn dev_info_lookup(major: u16, ver: u16) -> Option<DeviceInfo> {
    let mut fuzzy_match: Option<&DeviceInfo> = None;

    for i in DEV_INFO_TABLE {
        if i.major != major {
            continue;
        }
        let masked_ver = i.version & i.version_mask;
        if ver == 0 || masked_ver == 0 {
            fuzzy_match = Some(i);
        } else if ver == masked_ver.into() {
            return Some(DeviceInfo {
                major: i.major,
                dev_type: i.dev_type,
                version: i.version,
                version_mask: i.version_mask,
                name: i.name,
            });
        }
    }

    match fuzzy_match {
        Some(f) => Some(DeviceInfo {
            major: f.major,
            dev_type: f.dev_type,
            version: f.version,
            version_mask: f.version_mask,
            name: f.name,
        }),
        None => None,
    }
}

pub fn flash_ic_table_lookup(
    jedec_id0: u16, jedec_id1: u16, size: u32,
) -> Option<&'static FlashIcInfo> {
    FLASH_IC_TABLE
        .iter()
        .find(|ic| ic.jid0 as u16 == jedec_id0 && ic.jid1 as u16 == jedec_id1 && ic.size == size)
}
